def canCombine(set1, set2):
    for c in range(97, 123):
        lc = chr(c)  # 小写字符
        uc = chr(c - 32)  # 大写字符
        if (lc in set1 or uc in set1) and (lc in set2 or uc in set2):
            return True
    return False


def loop(eqs):
    for i in range(len(eqs)):
        for j in range(i + 1, len(eqs)):
            if canCombine(eqs[i], eqs[j]):
                tmp = list(eqs[i])
                tmp.extend(eqs[j])
                eqs[i] = set(tmp)
                eqs.pop(j)
                return True
    return False


